def formatmany(self, sql, many_params):
    # Initialize an empty list to store the formatted SQL parameters
    params_list = []

    # Iterate over each set of in-style parameters
    for params in many_params:
        # Initialize an empty dictionary to store the formatted SQL parameters
        # for the current set of parameters
        formatted_params = {}

        # Iterate over each parameter in the current set of parameters
        for param_name, param_value in params.items():
            # Check if the parameter is a tuple or a list
            if isinstance(param_value, (tuple, list)):
                # If the parameter is a tuple or a list, convert it to a list
                formatted_params[param_name] = list(param_value)
            else:
                # Otherwise, add the parameter to the dictionary
                formatted_params[param_name] = param_value

        # Add the formatted parameters for the current set of parameters to the list
        params_list.append(formatted_params)

    # Return the formatted SQL query and the list of formatted parameters
    return (sql, params_list)

