def _fromutc(self, dt):
    """
    Given a timezone-aware `datetime.datetime` in a given timezone, calculates a
    timezone-aware `datetime.datetime` in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    `datetime.datetime` object, we take this opportunity to determine whether the
    `datetime.datetime` is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous `datetime.datetime`).

    :param dt:
        A timezone-aware `datetime.datetime` object.
    """
    if not hasattr(dt, "fold"):
        return dt.astimezone(self.tz)
    if not dt.fold:
        return dt.astimezone(self.tz)
    return dt.replace(tzinfo=self.tz)

