    """
    Given command-line arguments with which this script was invoked, 
    parse the arguments and return them as a dict mapping from subparser name (or "global") to an
    argparse.Namespace instance.
    """
    parsed_arguments = {}
    for unparsed_arg in unparsed_arguments:
        # Use argparse to parse each subparser's arguments
        subparser_name, remaining_args = unparsed_arg.split(" ", 1)
        subparser_args = {
            # Parse the subparser arguments
            "subparser_name": subparser_name,
            "args": parse_subparser_args(remaining_args)
        }
        parsed_arguments[subparser_name] = argparse.Namespace(**subparser_args)

    # If there are no subparsers, all arguments are global
    if not subparser_args:
        parsed_arguments["global"] = argparse.Namespace(**parse_global_args(unparsed_arguments))

    return parsed_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    unclaimed_args = []

    for unparsed_arg in unparsed_arguments:
        if "--" in unparsed_arg:
            # Split the argument on "--" and get the subparser name
            subparser_name = unparsed_arg.split("--")[0]
            # Get the corresponding ArgumentParser from the subparsers dict
            subparser = subparsers[subparser_name]
            # Try to parse the argument using the subparser's parse_args method
            try:
                subparser_args = subparser.parse_args([unparsed_arg])
                # If the argument is parsed successfully, add it to the parsed_args dict
                # with the subparser name as the key
                parsed_args[subparser_name] = subparser_args
            except argparse.ArgumentError as e:
                # If there's an error parsing the argument, add it to the unclaimed_args list
                unclaimed_args.append(unparsed_arg)

    return parsed_args, unclaimed_args

