    """
    regex = re.compile(r'''
        (?P<arg> [^"]* "(?:\\.|[^"])*" [^"]*)  |  # argument in double quotes
        (?P<arg> [^'"]+)                           # argument not in quotes
      ''', re.VERBOSE)
    if platform == 'this':
        platform = 'posix' if os.name == 'posix' else 'cmd'
    if platform == 'posix':
        # ...
    elif platform == 'cmd':
        # ...
    else:
        raise NotImplementedError("Platform not supported")
    return regex.findall(s)

def addignored(ignored):
    cmd = 'git ls-files --others --exclude-standard'.split()
    result = subprocess.run(cmd, capture_output=True)
    if result.returncode != 0:
        raise Exception('Failed to get list of files to ignore')
    output = result.stdout.decode().splitlines()
    # remove comments from ignored string
    ignored = ignored.split(os.linesep)
    for line in ignored:
        if line.startswith('#'):
            ignored.remove(line)
    # remove any leading or trailing whitespace from ignored strings
    for line in ignored:
        line = line.strip()
    # remove duplicates
    ignored = list(dict.fromkeys(ignored))
    # remove any ignored files from the list of files to be committed
    for line in ignored:
        if line in output:
            output.remove(line)
    # return the list of files to be committed, separated by a comma
    return ','.join(output)

