def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not isinstance(args, (list, tuple)):
        args = [args]

    completed_processes = []

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("The `command` parameter must be a string or a list of strings.")

        completed_process = subprocess.run(command,
                                           args=args,
                                           cwd=cwd,
                                           stdout=subprocess.PIPE,
                                           stderr=subprocess.STDOUT,
                                           env=env,
                                           universal_newlines=True,
                                           check=True)
        completed_processes.append(completed_process)

        if verbose:
            print(completed_process.stdout)

    if hide_stderr:
        for completed_process in completed_processes:
            completed_process.stdout = ""

    if len(completed_processes) == 1:
        return completed_processes[0]
    else:
        return completed_processes

