def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files.

        :param parser_dict:
        :return:
        """
        result = {}
        for name, children in iteritems(parser_dict):
            if children is not None:
                if isinstance(children, OrderedDict):
                    for key, value in iteritems(children):
                        if value:
                            result.update(value)
            result[name] = children

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec = getattr(self, "spec", None)
    if not spec:
        raise Exception("spec not found")
    defaults = {}
    for arg in spec.args:
        # extract default from spec if available
        if isinstance(arg, str):
            if spec.get(arg):
                defaults[arg] = spec[arg]
        elif isinstance(arg, dict):
            # extract default from the subspec if available
            if isinstance(arg["name"], str):
                if spec[arg["name"]]:
                    defaults[arg["name"]] = spec[arg["name"]]
            elif isinstance(arg["default"], str):
                # otherwise, fallback to default value from arg
                defaults[arg["name"]] = arg["default"]
            else:
                # no default found, skip this argument
                continue
        elif isinstance(arg, list):
            # if the argument is a list, loop over its items and resolve defaults
            for item in arg:
                if isinstance(item, str):
                    if spec.get(item):
                        defaults[item] = spec[item]
                else:
                    raise Exception(f"Unknown argument type: {item}")
    return defaults

def get_deprecated_args():
    """Returning dict with options which deprecate others. """

    return {
        'oldArg': 'newArg'
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    Args:
        cli_args (dict): The dict of arguments from the command line.
        answer_file_args (dict): The dict of arguments from the answer file.
    """
    deprecated_arg_names = {
        'foo': 'bar',
        'baz': 'qux'
    }
    for arg, arg_name in deprecated_arg_names.items():
        if arg in cli_args:
            print("WARNING: The argument '{}' has been deprecated. Use '{}' instead.".format(arg, arg_name))
        elif arg in answer_file_args:
            print("WARNING: The argument '{}' has been deprecated. Use '{}' instead.".format(arg, arg_name))
    return cli_args, answer_file_args

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if command_name not in self.command_spec:
        raise ValueError("Command name {} not found".format(command_name))
    if argument_name not in self.command_spec[command_name]["arguments"]:
        raise ValueError("Argument name {} not found".format(argument_name))
    return self.command_spec[command_name]["arguments"][argument_name].get("accepts")

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    for arg in vars(args):
        if arg != None and arg[:2] == "--":
            silent_args.append(arg[2:])
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # get the function argspec
    argspec = getargspec(self)
    # check if all the required arguments are present
    for arg_name in argspec.args:
        if arg_name not in args:
            raise MissingRequiredArgumentError(f"Missing required argument: {arg_name}")
    # check if any of the given arguments are None
    for index, arg_name in enumerate(argspec.args):
        arg_value = args[index]
        if arg_value is None:
            raise InvalidArgumentError(f"Argument {arg_name} must not be None")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    matched_args = []
    for option in options_spec:
        if option.get("required_when"):
            try:
                condition_value = self.eval_option_expression(
                    option["required_when"], self.resolve_arg_references(args)
                )
                if bool(condition_value):
                    matched_args.append(option["name"])
            except:
                pass
    return matched_args

def validate_length_args(self, args):
    '''Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    '''
    for arg in args:
        try:
            length = arg['length']
            value = arg['value']
        except TypeError:
            raise TypeError('Invalid argument specified.')
        if len(value) > length:
            raise ValueError('Argument value is longer than specified length.')
        if len(value) < length:
            raise ValueError('Argument value is shorter than specified length.')

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for name, param in self._params.items():
        choices = param.get("choices")
        if choices is not None and args.get(name):
            if args[name] not in choices:
                msg = "Value of argument '{}' must be one of the available choices: {}."
                raise ValueError(msg.format(name, choices))
        if "case_sensitive" in param:
            case_sensitive = param["case_sensitive"]
            if case_sensitive is True:
                if args.get(name) is not None and args[name].lower() != name.lower():
                    msg = "Value of argument '{}' must match case of option '{}' exactly."
                    raise ValueError(msg.format(name, name))
    return args

def validate_min_max_args(args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Make sure the type of args is a list or a tuple
    if not isinstance(args, (list, tuple)):
        raise TypeError("expected a list or tuple, got {}".format(type(args).__name__))

    # Check if all elements in args are numbers
    if not all(isinstance(arg, numbers.Number) for arg in args):
        raise TypeError("expected all elements in args to be numbers")

    # Check if the length of args is greater than or equal to 2
    if len(args) < 2:
        raise TypeError("expected at least 2 elements in args")

    # Check if the length of args is less than or equal to 3
    if len(args) > 3:
        raise TypeError("expected at most 3 elements in args")

    # Check if all elements in args are between 0 and 100
    if not all(0 <= arg <= 100 for arg in args):
        raise ValueError("expected all elements in args to be between 0 and 100")

    # Check if the first and second elements in args are different
    if args[0] == args[1]:
        raise ValueError("expected the first and second elements in args to be different")

    # Check if the second and third elements in args are different
    if len(args) > 2 and args[1] == args[2]:
        raise ValueError("expected the second and third elements in args to be different")

    return args

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_vars = {}

    for arg in args:
        if arg in CONTROL_VARS:
            control_args[arg] = args[arg]
        elif arg in NESTED_VARS:
            nested_args[arg] = args[arg]
        elif arg in CUSTOM_VARS:
            custom_vars[arg] = args[arg]

    return control_args, nested_args, custom_vars

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :param playbook_path: the playbook to invoke.
    :param verbose: Ansible verbosity level.
    :param extra_vars: dict. Passed to Ansible as extra-vars.
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """

    if verbose is not None:
        if not isinstance(verbose, int):
            verbose = int(verbose)
            if verbose <= 0 or verbose > 5:
                raise ValueError(f"Invalid verbosity level: {verbose}")

    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise ValueError("Extra vars must be of type dict.")
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise ValueError(f"Ansible args must be of type dict, got {type(ansible_args)}")

    io = ir_plugin.getIO()

    command = [f"ansible-playbook", "-i", ir_plugin.get_inventory(), playbook_path, "--extra-vars", json.dumps(extra_vars or {})]
    command.extend(ansible_args or ["-v" if verbose is None else f"-{verbose}"])

    p = subprocess.Popen(command, stdout=io, stderr=io)
    _, stderr = p.communicate()

    if p.returncode != 0:
        raise RuntimeError(f"Ansible failed with code {p.returncode}")

def inject_config(self):
    if not os.environ.get('CONFIG_PATH'):
        os.environ['CONFIG_PATH'] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Root is not a prefix of the given path")
    cleaned_path = os.path.relpath(path, root)
    if cleaned_path.startswith(".."):
        raise ValueError("Path is not under the root directory")
    return cleaned_path
